"""抽象概念の土台（docs/foundation/index.html）。業務領域 ・ 目的レベル ・ 区切られた文脈の3つの層、パターン、13の境界、ユースケースの単位、ヘキサゴナル、ディレクトリ、いまの基盤との対応をタブでまとめる。
図は同じフォルダの <名前>.source.svg（class だけ）を design-svg resolve で <名前>.svg にしたもの。この台本は型に図を差し込むだけ。"""
import json, os, re
H = os.path.dirname(os.path.abspath(__file__))
TEMPLATE = '<title>抽象概念の土台</title>\n<meta name="claude:viewport-fit-sides" content="cover">\n<style>\n/* タブで層 ・ パターン ・ 境界 ・ 単位 ・ 文脈 ・ 六角形 ・ 置き場所 ・ 対応を切り替える */\n:root{--bg:#eef2f0;--card:#fff;--ink:#111d1a;--sub:#5b6b66;--line:#d3dcd8;--accent:#0d5c55;--accent-bg:#d5e6e3;--code:#f3f6f4;--f:"Noto Sans JP","Hiragino Kaku Gothic ProN",system-ui,sans-serif}\n@media (prefers-color-scheme:dark){:root:not([data-theme="light"]){--bg:#111614;--card:#192120;--ink:#e3ebe8;--sub:#9aaba5;--line:#2f3b37;--accent:#7cc4b7;--accent-bg:#1e3330;--code:#151c1a;color-scheme:dark}}\n:root[data-theme="dark"]{--bg:#111614;--card:#192120;--ink:#e3ebe8;--sub:#9aaba5;--line:#2f3b37;--accent:#7cc4b7;--accent-bg:#1e3330;--code:#151c1a;color-scheme:dark}\n[hidden]{display:none!important}\nbody{background:var(--bg);color:var(--ink);font:15px/1.75 var(--f);padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));padding-block:20px 56px}\nmain{max-width:1240px;margin:0 auto;display:flex;flex-direction:column;gap:14px}\nh1{font-size:24px;margin:0} h2{font-size:18px;margin:0;color:var(--accent)} h3{font-size:15px;margin:8px 0 0} p{margin:0}\n.tabs{display:flex;gap:6px;overflow-x:auto;padding-bottom:4px;position:sticky;top:env(safe-area-inset-top,0px);background:var(--bg);z-index:2;padding-top:6px}\n.tabs button{flex:0 0 auto;font:inherit;font-size:14px;border:1px solid var(--line);background:var(--card);color:var(--ink);border-radius:999px;padding:4px 14px;cursor:pointer}\n.tabs button[aria-selected="true"]{background:var(--accent-bg);border-color:var(--accent);color:var(--accent);font-weight:700}\n.tabs button:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\nsection{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:16px 18px;min-width:0;display:flex;flex-direction:column;gap:12px}\n.ans{border-left:4px solid var(--accent);padding:8px 14px;font-weight:700;max-width:95ch}\n.read{font-size:14px;color:var(--sub);max-width:100ch}\n.fig,.tw{overflow-x:auto}\ntable{border-collapse:collapse;width:100%;font-size:13.5px} th,td{border-bottom:1px solid var(--line);padding:7px 8px;text-align:left;vertical-align:top} th{font-size:12px;color:var(--sub);font-weight:500;white-space:nowrap}\ndetails{border-top:1px solid var(--line);padding-top:8px} summary{cursor:pointer;color:var(--accent);font-size:14px} details[open] summary{margin-bottom:8px}\n.lead{font-size:16px;font-weight:700}\n.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,200px),1fr));gap:8px}\n.card{background:var(--accent-bg);border-radius:8px;padding:8px 12px;display:flex;flex-direction:column;gap:2px;min-width:0} .card b{color:var(--accent);font-size:14px} .card span{font-size:13px}\n.chips{display:flex;flex-wrap:wrap;gap:6px} .chips span{background:var(--code);border:1px solid var(--line);border-radius:999px;padding:2px 12px;font-size:13px}\nol.steps{margin:0;padding-left:1.4em;font-size:14px}\n</style>\n<main>\n<h1>抽象概念の土台</h1>\n<nav class="tabs" role="tablist" aria-label="内容"><button type="button" role="tab" id="t-overview" aria-controls="p-overview" aria-selected="true">全体像</button><button type="button" role="tab" id="t-layers" aria-controls="p-layers" aria-selected="false">3つの層</button><button type="button" role="tab" id="t-patterns" aria-controls="p-patterns" aria-selected="false">パターン</button><button type="button" role="tab" id="t-boundaries" aria-controls="p-boundaries" aria-selected="false">13の境界</button><button type="button" role="tab" id="t-usecases" aria-controls="p-usecases" aria-selected="false">ユースケース</button><button type="button" role="tab" id="t-contexts" aria-controls="p-contexts" aria-selected="false">文脈</button><button type="button" role="tab" id="t-hexagonal" aria-controls="p-hexagonal" aria-selected="false">ヘキサゴナル</button><button type="button" role="tab" id="t-layout" aria-controls="p-layout" aria-selected="false">ディレクトリ</button><button type="button" role="tab" id="t-mapping" aria-controls="p-mapping" aria-selected="false">基盤との対応</button></nav>\n<section role="tabpanel" id="p-overview" aria-labelledby="t-overview"><h2>全体像</h2><p class="lead">Semantic Agent Schema を設計 ・ 実装するための抽象概念。3つの層を分けて持ち、どの形を選んでも13の境界を守る。</p><div class="fig">{{FIG:layers}}</div><div class="cards"><div class="card"><b>層1 業務領域</b><span>見つける。線は「分解」</span></div><div class="card"><b>層2 目的レベル</b><span>ユースケースの高さ。線は「呼び出し」</span></div><div class="card"><b>層3 区切られた文脈</b><span>設計する。線は「連係」</span></div></div><p class="read">この土台は、基盤自身を設計するときにも、基盤で何かを設計するときにも同じ概念として使う。目的は、あとから「この文脈で分けたのは間違いだった」と作り直さないこと。</p></section><section role="tabpanel" id="p-layers" aria-labelledby="t-layers" hidden><h2>3つの層</h2><p class="lead">業務領域は見つけるもの、文脈は設計するもの。対応は1対1に限らない。</p><div class="fig">{{FIG:problem-solution}}</div><div class="cards"><div class="card"><b>下へ：どのように？</b><span>目的を手順へ分ける</span></div><div class="card"><b>上へ：なぜ？</b><span>手順をまとめて1つ上の目的へ</span></div><div class="card"><b>外へ：設計の範囲</b><span>一番外側に要約を書く（別の軸）</span></div></div><details><summary>詳しい表</summary><div class="tw"><table><thead><tr><th>層</th><th>何を表すか</th><th>線の意味</th><th>決め方</th></tr></thead><tbody><tr><td>層1\u3000業務領域</td><td>事業活動を細かく分けたもの。何をするかを表す。見つける（問題の側）</td><td>分解：事業活動を細かく分ける</td><td>ユースケースの3条件（同じアクター ・ 同じ外部システム ・ 密接なデータ）でまとまるまで分ける。補完 ・ 一般は分けても区分が変わらなければ止め、中核はできる限り正確に区切る</td></tr><tr><td>層2\u3000目的レベル</td><td>主体の目的の高さ。要約（＋）・ ユーザー目的（！）・ サブ機能（－）</td><td>呼び出し：なぜ？で上、どのように？で下</td><td>目的レベルと設計の範囲は別の軸として持つ</td></tr><tr><td>層3\u3000区切られた文脈</td><td>1つのモデルと言葉が通じる範囲。設計する（解決の側）</td><td>連係：上流 ・ 下流と、その方法</td><td>言葉の一貫と、同じデータを扱うユースケースの集まりで線を引く</td></tr></tbody></table></div></details></section><section role="tabpanel" id="p-patterns" aria-labelledby="t-patterns" hidden><h2>パターン</h2><p class="lead">層ごとに選ぶ。文脈は「広い1つ」から始める。</p><div class="fig">{{FIG:patterns}}</div><details><summary>詳しい表</summary><div class="tw"><table><thead><tr><th>層</th><th>パターン</th><th>選ぶとき</th></tr></thead><tbody><tr><td>層1</td><td>細分化</td><td>事業活動を、3条件でまとまるまで分ける。中核はできる限り正確に</td></tr><tr><td>層2</td><td>要約 → ユーザー目的 → サブ機能</td><td>サブ機能は、読みやすくするときか、ほかから何度も使うときだけ書く</td></tr><tr><td>層2</td><td>なぜ？で上げる</td><td>手順をまとめて1つ上の目的にする（目的レベルの軸）</td></tr><tr><td>層2</td><td>一番外側に要約を書く</td><td>設計の範囲の軸。主体が外にいる一番外側の範囲で、いつも書くことを勧める</td></tr><tr><td>層3</td><td>広い1つの文脈（中を業務領域の論理的な境界で分ける）</td><td>業務の理解が浅い ・ 変更が多い ・ 小さいチーム</td></tr><tr><td>層3</td><td>部分木を文脈として切り出す（論理 → 物理）</td><td>業務知識が増えて安定し、言葉 ・ チーム ・ ライフサイクルが分かれたとき</td></tr><tr><td>層3</td><td>1つの業務領域に複数のモデル</td><td>課題ごとにモデルが違うとき。モデルごとに別の文脈に置く</td></tr><tr><td>層3</td><td>連係を選ぶ：共用サービス（公開された言葉を出す）・ モデル変換装置 ・ 従属 ・ 良きパートナー</td><td>文脈どうしをつなぐとき。どれを選んだかを明示する</td></tr><tr><td>層3</td><td>互いに独立（重複して実装する）</td><td>一般 ・ 補完の業務領域だけ。中核には使えない</td></tr><tr><td>層3</td><td>モデルの共有</td><td>例外。1つのチームが複数の文脈を持つとき、境界を明確にする手段として使う</td></tr></tbody></table></div></details></section><section role="tabpanel" id="p-boundaries" aria-labelledby="t-boundaries" hidden><h2>13の境界</h2><p class="lead">パターンは選ぶもの、境界は守るもの。どの境界も、防ぐ失敗を1つ持つ。</p><div class="fig">{{FIG:boundaries}}</div><details><summary>防ぐ失敗と出どころ</summary><div class="tw"><table><thead><tr><th>#</th><th>境界</th><th>防ぐ失敗</th><th>出どころ</th></tr></thead><tbody><tr><td>1</td><td>業務領域は事業活動に届くもので、まとまりはユースケースの3条件で決める。都合で入れない</td><td>業務領域の中身が目的と関係なく増え、あとで業務領域を分け直すことになる</td><td>ddd-advisor ・ あなたの「分解」</td></tr><tr><td>2</td><td>呼び出しの親子には「なぜ？」で届く目的だけを入れる。サブ機能は、複数から使われるか呼び出し側が読みにくくなるときに切り出し、親を1つに決めない。ユーザー目的から別のユーザー目的を呼んでもよい</td><td>どの目的のための手順かを辿れなくなり、サブ機能が乱立する</td><td>usecase-advisor</td></tr><tr><td>3</td><td>目的レベル ・ 設計の範囲 ・ 業務領域は別々の分類として持つ。区分（中核 ・ 補完 ・ 一般）でディレクトリの置き場所を決めない（区分は実装方法と連係の選び方を決める）</td><td>1つの分類から他を決めつけ、置き場所や実装を誤る。区分が変わるたびに組み替える</td><td>usecase-advisor ・ ddd-advisor</td></tr><tr><td>4</td><td>どのユースケースにもレベル欄とスコープ欄を持たせる</td><td>高さの違うユースケースを、印なしで同じ並びに置いてしまう</td><td>usecase-advisor</td></tr><tr><td>5</td><td>低すぎる目的はユースケースにせず、呼ぶ側の手順に含める</td><td>細かすぎるユースケースが増え、追跡とテストの手間が増える</td><td>usecase-advisor</td></tr><tr><td>6</td><td>ユースケースを1つずつクラスやフォルダに対応づけない</td><td>ユースケースを足すたびに、コードの構造を組み替えることになる</td><td>usecase-advisor</td></tr><tr><td>7</td><td>同じデータを扱うユースケースの集まりを、文脈の線で割らない</td><td>同じデータを扱う処理が2つの文脈に分かれ、一貫性が壊れる</td><td>ddd-advisor</td></tr><tr><td>8</td><td>1つの文脈に、競合するモデルを入れない</td><td>1つの文脈の中で言葉の意味が割れる</td><td>ddd-advisor</td></tr><tr><td>9</td><td>文脈どうしは連係方法を明示して選ぶ。中核を含む下流は従属しない</td><td>つなぎ方が暗黙になり、上流の変更で中核が壊れる</td><td>ddd-advisor</td></tr><tr><td>10</td><td>1つの文脈は1つのチームだけが持つ（AI の子のセッションに当てはめるかは推測）</td><td>1つの文脈を複数で直し、変更がぶつかる</td><td>ddd-advisor</td></tr><tr><td>11</td><td>1つの集約を2つの文脈に分けない</td><td>1つの集約の不変条件を2か所で守ることになり、破れる</td><td>ddd-advisor</td></tr><tr><td>12</td><td>集約の状態は、集約の中の業務ロジックだけが変える。外には参照だけ</td><td>外から状態が変えられ、不変条件が守れない</td><td>ddd-advisor</td></tr><tr><td>13</td><td>1つのトランザクションで変える集約は1つ</td><td>1回の変更で複数の集約を書き、一部だけ失敗したときに整合が崩れる</td><td>ddd-advisor</td></tr></tbody></table></div></details></section><section role="tabpanel" id="p-usecases" aria-labelledby="t-usecases" hidden><h2>ユースケース</h2><p class="lead">単位はユーザー目的。validate は入口のコマンドで、ユースケースではない。</p><div class="fig">{{FIG:usecase-units}}</div><details><summary>U8 の1回が通る役割（図）</summary><div class="fig">{{FIG:validate-flow}}</div></details><h3>いま境界に反している U</h3><div class="chips"><span>全件：レベル欄とスコープ欄が無い（境界4）</span><span>U0 ・ U27：要約の下のユーザー目的が書かれていない</span><span>U23 ・ U24 ・ U7：高さ違いや重なりの疑い（欄を足してから確かめる）</span></div></section><section role="tabpanel" id="p-contexts" aria-labelledby="t-contexts" hidden><h2>文脈</h2><p class="lead">この基盤は型1（広い1つの文脈）。言葉が分かれたら切り出す。</p><div class="fig">{{FIG:context-types}}</div><details><summary>型ごとのディレクトリ</summary><div class="tw"><table><thead><tr><th>型</th><th>選ぶとき</th><th>ディレクトリ</th></tr></thead><tbody><tr><td>型1\u3000広い1つの文脈</td><td>理解が浅い ・ 変更が多い ・ 小さいチーム ・ 言葉を共有している</td><td>repo ＝ 文脈。中を業務領域の論理的な境界で分ける</td></tr><tr><td>型2\u30001対1</td><td>業務領域ごとに言葉や変わる速さが違う ・ チームが分かれている</td><td>contexts/&lt;業務領域&gt;/ がそれぞれ六角形と外へ出す言葉を持つ</td></tr><tr><td>型3\u3000まとめて分ける</td><td>言葉を共有する業務領域とそうでないものがはっきりしている</td><td>contexts/&lt;束ねた文脈&gt;/ の中に業務領域</td></tr><tr><td>型4\u30001つの業務領域を複数の文脈で扱う</td><td>課題ごとにモデルが違うとき。割らないのは、同じデータのユースケースの集まりと集約</td><td>同じ業務領域が、モデルごとに別の文脈に入る</td></tr></tbody></table></div></details></section><section role="tabpanel" id="p-hexagonal" aria-labelledby="t-hexagonal" hidden><h2>ヘキサゴナル</h2><p class="lead">コアは domain と application。ポートは、その会話を受け持つ業務領域の application が持つ。</p><div class="cards"><div class="card"><b>ユースケース</b><span>目的を果たす手順と判断（application の use_cases）</span></div><div class="card"><b>ドメイン</b><span>値を受け取り値を返す（domain）</span></div><div class="card"><b>ポート</b><span>外に頼む1回の約束。会話の目的で決める（application の ports）</span></div><div class="card"><b>アダプター</b><span>その1回を技術で実現する（adapters の outbound）</span></div></div><div class="fig">{{FIG:hexagon}}</div><details><summary>ポートの持ち主と使う業務領域</summary><div class="tw"><table><thead><tr><th>ポート（会話の目的）</th><th>持ち主の業務領域</th><th>使う業務領域</th><th>アダプター</th></tr></thead><tbody><tr><td>文書を保管する</td><td>保存と版の管理</td><td>ほぼすべて</td><td>fs</td></tr><tr><td>確定した姿と比べる</td><td>保存と版の管理</td><td>変更の確かめ</td><td>git</td></tr><tr><td>変更の記録と承認を残し、たどる</td><td>変更の確かめ</td><td>変更の確かめ</td><td>sqlite</td></tr><tr><td>承認された欄を問う</td><td>意味の検証</td><td>意味の検証</td><td>sqlite</td></tr><tr><td>rule の判定を残し、使い直す</td><td>意味の検証</td><td>意味の検証</td><td>fs</td></tr><tr><td>任せる先に依頼する</td><td>AI と外のツールによる判定</td><td>意味の検証（のちにセッション）</td><td>tools ・ coding-agents</td></tr></tbody></table></div></details></section><section role="tabpanel" id="p-layout" aria-labelledby="t-layout" hidden><h2>ディレクトリ</h2><p class="lead">業務領域が上、その下に domain と application。モジュラーモノリスと同じ形。</p><div class="fig">{{FIG:directories}}</div><details><summary>置き方の決まり</summary><ul class="steps"><li>core/&lt;業務領域&gt;/ の下に domain（概念）と application（use_cases ・ ports）の2つの crate。1つにすると業務領域どうしの依存が循環する</li><li>ポートは、その会話を受け持つ業務領域の application に置く。共有の置き場は作らない</li><li>ユースケースは1つにつき1ファイルにしない（境界6）。目的レベルでフォルダを分けない（境界3）</li><li>外側は inbound（入口）と outbound（外の技術）。HTTP の API を足すときは inbound に足す</li><li>Cargo の勧め（平らに並べる）から外れることと理由は CODING.md に書き、フォルダと crate 名の一致は検査で守る</li></ul></details>{{TREE}}</section><section role="tabpanel" id="p-mapping" aria-labelledby="t-mapping" hidden><h2>基盤との対応</h2><p class="lead">いまの基盤にある語と、この土台の概念の対応。</p><div class="fig">{{FIG:mapping}}</div><h3>この土台で、次に設計すること</h3><ol class="steps"><li>U0〜U28 にレベル欄とスコープ欄を足し、境界に照らして直す</li><li>ポートとディレクトリの形を、ACDR で実装へ移す</li><li>この概念を基盤がどこまで持つか（語彙 ・ 一緒に配るもの ・ 使う側の宣言）を、直したユースケースから決める</li></ol></section>\n</main>\n<script>\n(function(){\n  var bs=[].slice.call(document.querySelectorAll(\'.tabs button\'));\n  function show(k){bs.forEach(function(b){var on=b.id===\'t-\'+k;b.setAttribute(\'aria-selected\',on?\'true\':\'false\');document.getElementById(b.getAttribute(\'aria-controls\')).hidden=!on;});\n    try{localStorage.setItem(\'tab\',k)}catch(e){}}\n  bs.forEach(function(b){b.addEventListener(\'click\',function(){show(b.id.slice(2));window.scrollTo({top:0})})});\n  var h=(location.hash||\'\').slice(1); var s=null; try{s=localStorage.getItem(\'tab\')}catch(e){}\n  var k=document.getElementById(\'t-\'+h)?h:(s&&document.getElementById(\'t-\'+s)?s:null); if(k) show(k);\n})();\n</script>\n'
# ディレクトリのタブの「実際のディレクトリ構成」。左の木のファイルを押すと、右に役割 ・ 担うこと ・ コードのイメージが出る
TREE = r'''<h3>実際のディレクトリ構成</h3>
<p class="read">図の形をファイルまで下ろしたもの。左のファイルを押すと、役割 ・ 担うこと ・ コードのイメージが出る。コードは形を伝えるための抜粋で、そのまま動くものではない。いまのコードはまだこの形に移していない（ACDR で移す）。</p>
<style>
.lw{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.1fr);gap:12px;align-items:start}
@media (max-width:860px){.lw{grid-template-columns:1fr}}
.lt{font:13px/1.55 ui-monospace,Menlo,monospace;overflow-x:auto;border:1px solid var(--line);border-radius:8px;padding:8px}
.lt .row{display:flex;gap:8px;align-items:baseline;white-space:nowrap;padding:1px 6px;border-radius:6px}
.lt button{all:unset;cursor:pointer;color:var(--accent)} .lt button:focus-visible{outline:2px solid var(--accent)}
.lt .row.on{background:var(--accent-bg)} .lt .dir{font-weight:700} .lt .note{font:12px var(--f);color:var(--sub)}
.ld{border:1px solid var(--line);border-radius:8px;padding:10px 12px;display:flex;flex-direction:column;gap:6px;min-width:0;position:sticky;top:56px;scroll-margin-top:56px}
@media (max-width:860px){.ld{position:static}}
.ld .p{font:12.5px ui-monospace,Menlo,monospace;color:var(--sub);word-break:break-all} .ld b{font-size:16px;color:var(--accent)}
.ld ul{margin:0;padding-left:1.2em;font-size:14px} .ld .lbl{font-size:12px;color:var(--sub);font-weight:700}
.ld pre{margin:0;background:var(--code);border-radius:8px;padding:10px 12px;overflow-x:auto;font:12.5px/1.6 ui-monospace,Menlo,monospace}
</style>
<div class="lw"><div class="lt" id="lt"></div><div class="ld" id="ld"></div></div>
<script>
(function(){
  var T=__T__, tree=document.getElementById('lt'), det=document.getElementById('ld');
  function esc(s){return String(s).replace(/[&<>]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;'}[c]})}
  function show(i){var e=T[i];
    [].forEach.call(tree.querySelectorAll('.row'),function(r){r.classList.toggle('on',r.dataset.i==String(i))});
    det.innerHTML='<div class="p">'+esc(e.path)+'</div><b>'+esc(e.role)+'</b><div class="lbl">担うこと</div><ul>'+e.does.map(function(x){return '<li>'+esc(x)+'</li>'}).join('')+'</ul><div class="lbl">コードのイメージ</div><pre>'+esc(e.code)+'</pre>';}
  var notes={}; T.forEach(function(e){if(e.kind==='dir')notes[e.path]=e.note});
  var seen={};
  T.forEach(function(e,i){var parts=e.path.replace(/\/$/,'').split('/');
    for(var k=1;k<=parts.length;k++){var file=(k===parts.length&&e.kind==='file');var p=parts.slice(0,k).join('/')+(file?'':'/');
      if(seen[p])continue;seen[p]=1;
      var r=document.createElement('div');r.className='row';r.style.paddingLeft=(6+(k-1)*16)+'px';
      if(!file){r.innerHTML='<span class="dir">'+esc(parts[k-1])+'/</span>'+(notes[p]?'<span class="note">'+esc(notes[p])+'</span>':'');}
      else{r.dataset.i=i;var b=document.createElement('button');b.type='button';b.textContent=parts[k-1];b.onclick=(function(n){return function(){show(n);if(window.matchMedia('(max-width:860px)').matches)det.scrollIntoView({block:'start'})}})(i);r.appendChild(b);
        var t=document.createElement('span');t.className='note';t.textContent=e.role;r.appendChild(t);}
      tree.appendChild(r);}});
  var start=0;T.forEach(function(e,i){if(/verify\.rs$/.test(e.path))start=i});show(start);
})();
</script>'''

def fig(m):
    return open(os.path.join(H, m.group(1) + '.svg')).read()
out = re.sub(r'\{\{FIG:([a-z0-9-]+)\}\}', fig, TEMPLATE)
tree = json.dumps(json.load(open(os.path.join(H, 'layout.json')))['entries'], ensure_ascii=False).replace('</', '<\\/')
out = out.replace('{{TREE}}', TREE.replace('__T__', tree))
open(os.path.join(H, 'index.html'), 'w').write(out)
